import { Drive } from '@momots/drive';

const drive = new Drive()
  .use('/account/**', async (ctx, next) => {
    // Before the request: add credentials to account endpoints
    const token = getToken();
    if (token) {
      ctx.req.headers.set('Authorization', `Bearer ${token}`);
    }
    await next();
  })
  .use('*', async (ctx, next) => {
    await next();
    // After the response: log every endpoint status, including 401
    console.log({
      method: ctx.req.method,
      path: ctx.path,
      status: ctx.res.status,
    });
  });

// Call sites only specify which endpoint to access
drive.get({ api: '/account/profile' });
drive.get({ api: '/account/orders' });
// The product catalog only matches the response logging rule
drive.get({ api: '/catalog/products' });

