const periods = [
  { value: 'Daily', label: 'Daily' },
  { value: 'Weekly', label: 'Weekly' },
  { value: 'Monthly', label: 'Monthly' },
];

function ReminderSettings() {
  // Keep state outside the panel so it survives collapsing
  const [period, setPeriod] = useState('Weekly');
  const [minutes, setMinutes] = useState(25);

  return (
    <Accordion
      defaultValue={['reminder']}
      options={[{
        value: 'reminder',
        label: `${period} reminder · notify ${minutes} minutes ahead`,
        content: (
          <>
            <ToggleGroup
              variant="segmented"
              options={periods}
              value={period}
              onChange={(next) => { if (next) setPeriod(next); }}
            />
            <Slider
              label="Advance notice"
              min={5}
              max={60}
              step={5}
              value={minutes}
              formatValue={(value) => `${value} minutes ahead`}
              onValueChange={setMinutes}
            />
          </>
        ),
      }]}
    />
  );
}
